import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:logger/logger.dart';
import 'package:flutter_libepiccash/lib.dart' as lib_epic;
import 'package:path_provider/path_provider.dart';
